def rd(f):
    return open(os.path.join(ROOT, f), encoding="utf-8", errors="replace").read()
def bump(t):
    for i in range(len(t) - 1, -1, -1):
        if t[i] in "0123456789": return t[:i] + str((int(t[i]) + 1) % 10) + t[i + 1:]
    return t + "!"
